:root {
  --ink: #e8f7ff;
  --muted: #8aa2b8;
  --cyan: #46e8ff;
  --cyan-soft: rgba(70, 232, 255, 0.18);
  --magenta: #ff3f9e;
  --amber: #ffd166;
  --green: #7cffb2;
  --danger: #ff4d6d;
  --panel: rgba(7, 12, 26, 0.82);
  --line: rgba(120, 220, 255, 0.22);
  --mono: ui-monospace, "SFMono-Regular", "Cascadia Mono", "Segoe UI Mono", Menlo, Consolas, monospace;
  --sans: "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;
}

* { box-sizing: border-box; }

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: #04060e;
  color: var(--ink);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  user-select: none;
}

body {
  position: fixed;
  inset: 0;
  touch-action: none;
}

#game {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  cursor: crosshair;
  outline: none;
  touch-action: none;
}

#vignette {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.4s ease;
  box-shadow:
    inset 0 0 140px rgba(255, 45, 90, 0.32),
    inset 0 0 40px rgba(255, 45, 90, 0.22);
  animation: dangerPulse 1.1s ease-in-out infinite alternate;
}

#vignette.danger { opacity: 1; }

@keyframes dangerPulse {
  from { opacity: 0.45; }
  to { opacity: 0.95; }
}

/* ------------------------------------------------------------------ HUD */

.hud {
  position: absolute;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 20px 26px 18px;
  font-family: var(--mono);
  text-shadow: 0 1px 10px rgba(0, 0, 0, 0.85);
}

.hud-top {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: start;
  gap: 18px;
}

.stat-block {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
}

.stat-label,
.meter-label {
  color: var(--muted);
  font-size: 10px;
  letter-spacing: 0.32em;
  font-weight: 700;
}

.stat-value {
  color: var(--cyan);
  font-size: clamp(24px, 3.1vw, 38px);
  line-height: 1;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-shadow: 0 0 18px rgba(70, 232, 255, 0.55);
}

.best-line {
  color: rgba(138, 162, 184, 0.7);
  font-size: 10px;
  letter-spacing: 0.22em;
  margin-top: 3px;
}

.wave-block {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  text-align: center;
  min-width: 210px;
}

.wave-label {
  color: var(--ink);
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.36em;
}

.wave-name {
  color: var(--magenta);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.3em;
  text-shadow: 0 0 14px rgba(255, 63, 158, 0.55);
}

.boss-wrap {
  width: min(340px, 34vw);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  margin-top: 7px;
}

.boss-track {
  width: 100%;
  height: 5px;
  border: 1px solid rgba(255, 63, 158, 0.35);
  background: rgba(255, 63, 158, 0.1);
  transform: skewX(-24deg);
  overflow: hidden;
}

.boss-fill {
  height: 100%;
  width: 100%;
  background: linear-gradient(90deg, #ff3f9e, #ff9d5c);
  box-shadow: 0 0 14px rgba(255, 63, 158, 0.8);
  transition: width 0.12s linear;
}

.boss-name {
  color: var(--magenta);
  font-size: 9px;
  letter-spacing: 0.3em;
  font-weight: 700;
}

.right-block {
  display: flex;
  align-items: flex-start;
  justify-content: flex-end;
  gap: 18px;
}

.meter-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
  align-items: flex-end;
}

.shields,
.bombs {
  display: flex;
  gap: 5px;
}

.pip {
  width: 15px;
  height: 18px;
  display: block;
  background: rgba(70, 232, 255, 0.08);
  border: 1px solid rgba(70, 232, 255, 0.28);
  clip-path: polygon(50% 0, 100% 27%, 100% 73%, 50% 100%, 0 73%, 0 27%);
  transition: background 0.15s ease, box-shadow 0.15s ease;
}

.pip.on {
  background: var(--cyan);
  border-color: var(--cyan);
  box-shadow: 0 0 10px rgba(70, 232, 255, 0.85);
}

.bomb-pip {
  width: 13px;
  height: 13px;
  display: block;
  background: rgba(255, 209, 102, 0.08);
  border: 1px solid rgba(255, 209, 102, 0.32);
  transform: rotate(45deg);
  transition: background 0.15s ease, box-shadow 0.15s ease;
}

.bomb-pip.on {
  background: var(--amber);
  border-color: var(--amber);
  box-shadow: 0 0 10px rgba(255, 209, 102, 0.8);
}

.hud-buttons {
  display: flex;
  gap: 7px;
  pointer-events: auto;
}

.icon-btn {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 1px solid var(--line);
  background: rgba(7, 14, 30, 0.6);
  color: var(--cyan);
  font-family: var(--mono);
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}

.icon-btn:hover,
.icon-btn:focus-visible {
  background: rgba(70, 232, 255, 0.16);
  border-color: var(--cyan);
  outline: none;
}

.icon-btn.muted {
  color: var(--muted);
  border-color: rgba(138, 162, 184, 0.25);
  text-decoration: line-through;
}

.hud-bottom {
  position: relative;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  min-height: 44px;
}

.powerups {
  position: absolute;
  left: 0;
  bottom: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
  align-items: flex-start;
}

.chip {
  --p: 0%;
  display: none;
  align-items: center;
  gap: 8px;
  font-size: 9px;
  letter-spacing: 0.2em;
  color: var(--cyan);
  font-weight: 700;
}

.chip.show { display: flex; }

.chip i {
  display: block;
  width: 68px;
  height: 3px;
  background: rgba(70, 232, 255, 0.14);
  box-shadow: inset 0 0 0 1px rgba(70, 232, 255, 0.12);
  position: relative;
  overflow: hidden;
}

.chip i::after {
  content: "";
  position: absolute;
  inset: 0;
  width: var(--p);
  background: var(--cyan);
  box-shadow: 0 0 8px rgba(70, 232, 255, 0.8);
}

.chip[data-power="spread"] { color: var(--green); }
.chip[data-power="spread"] i { background: rgba(124, 255, 178, 0.14); }
.chip[data-power="spread"] i::after { background: var(--green); box-shadow: 0 0 8px rgba(124, 255, 178, 0.8); }
.chip[data-power="power"] { color: var(--amber); }
.chip[data-power="power"] i { background: rgba(255, 209, 102, 0.14); }
.chip[data-power="power"] i::after { background: var(--amber); box-shadow: 0 0 8px rgba(255, 209, 102, 0.8); }

.combo {
  color: var(--amber);
  font-size: clamp(22px, 2.4vw, 32px);
  font-weight: 900;
  letter-spacing: 0.04em;
  text-shadow: 0 0 22px rgba(255, 209, 102, 0.7);
  transform-origin: center bottom;
}

.combo.bump { animation: comboBump 0.22s ease-out; }

@keyframes comboBump {
  0% { transform: scale(1.35); }
  100% { transform: scale(1); }
}

.bomb-btn {
  position: absolute;
  right: 0;
  bottom: 0;
  display: none;
  width: 74px;
  height: 74px;
  border-radius: 50%;
  border: 1px solid rgba(255, 209, 102, 0.55);
  background: radial-gradient(circle at 35% 30%, rgba(255, 209, 102, 0.24), rgba(20, 12, 4, 0.7));
  color: var(--amber);
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.14em;
  box-shadow: 0 0 22px rgba(255, 209, 102, 0.2), inset 0 0 18px rgba(255, 209, 102, 0.08);
  pointer-events: auto;
  cursor: pointer;
  touch-action: manipulation;
}

.bomb-btn:active { transform: scale(0.94); }

.hint {
  position: absolute;
  left: 50%;
  bottom: 6px;
  transform: translateX(-50%);
  color: rgba(170, 205, 225, 0.55);
  font-size: 9px;
  letter-spacing: 0.22em;
  white-space: nowrap;
  transition: opacity 0.8s ease;
}

.hint.fade { opacity: 0; }

/* ----------------------------------------------------------------- toast */

.toast {
  position: absolute;
  top: 21%;
  left: 50%;
  transform: translate(-50%, -10px);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  text-align: center;
  opacity: 0;
  pointer-events: none;
  white-space: nowrap;
}

.toast.show { animation: toastIn 2.4s cubic-bezier(0.16, 1, 0.3, 1) forwards; }

.toast-kicker {
  color: var(--cyan);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.42em;
  text-shadow: 0 0 14px rgba(70, 232, 255, 0.7);
}

.toast-title {
  font-family: var(--sans);
  font-size: clamp(26px, 4.4vw, 54px);
  font-weight: 900;
  letter-spacing: 0.1em;
  color: #fff;
  text-shadow: 0 0 26px rgba(70, 232, 255, 0.65), 0 2px 20px rgba(0, 0, 0, 0.8);
}

.toast-sub {
  color: var(--magenta);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.34em;
}

.toast.good .toast-kicker,
.toast.good .toast-sub { color: var(--green); text-shadow: 0 0 14px rgba(124, 255, 178, 0.6); }
.toast.danger .toast-kicker,
.toast.danger .toast-sub { color: var(--danger); text-shadow: 0 0 14px rgba(255, 77, 109, 0.7); }

@keyframes toastIn {
  0% { opacity: 0; transform: translate(-50%, 14px) scale(0.96); }
  12% { opacity: 1; transform: translate(-50%, 0) scale(1); }
  72% { opacity: 1; transform: translate(-50%, 0) scale(1); }
  100% { opacity: 0; transform: translate(-50%, -16px) scale(1.02); }
}

/* --------------------------------------------------------------- overlays */

.overlay {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: grid;
  place-items: center;
  padding: 28px;
  background:
    radial-gradient(ellipse at 50% 42%, rgba(8, 18, 40, 0.18) 0%, rgba(4, 6, 14, 0.7) 62%, rgba(3, 4, 10, 0.94) 100%);
  backdrop-filter: blur(2px);
  -webkit-backdrop-filter: blur(2px);
}

.overlay.is-hidden,
.is-hidden { display: none !important; }

.menu-overlay {
  background:
    radial-gradient(ellipse at 50% 45%, rgba(10, 24, 52, 0.08) 0%, rgba(4, 6, 14, 0.52) 55%, rgba(3, 4, 10, 0.9) 100%);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

.menu-inner {
  width: min(760px, 94vw);
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  animation: menuIn 0.7s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes menuIn {
  from { opacity: 0; transform: translateY(18px); }
  to { opacity: 1; transform: translateY(0); }
}

.sigil {
  position: relative;
  width: 78px;
  height: 78px;
  margin-bottom: 18px;
  display: grid;
  place-items: center;
  filter: drop-shadow(0 0 16px rgba(70, 232, 255, 0.45));
}

.sigil-ring {
  position: absolute;
  border-radius: 50%;
  border: 1px solid rgba(70, 232, 255, 0.4);
}

.sigil-ring.r1 {
  inset: 0;
  border-style: dashed;
  animation: spin 18s linear infinite;
}

.sigil-ring.r2 {
  inset: 13px;
  border-color: rgba(255, 63, 158, 0.4);
  animation: spin 11s linear infinite reverse;
}

@keyframes spin { to { transform: rotate(360deg); } }

.sigil-ship {
  width: 0;
  height: 0;
  border-left: 13px solid transparent;
  border-right: 13px solid transparent;
  border-bottom: 32px solid var(--cyan);
  filter: drop-shadow(0 0 8px rgba(70, 232, 255, 0.9));
  transform: translateY(-3px);
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 14px;
  margin: 0 0 12px;
  color: var(--muted);
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.36em;
  text-transform: uppercase;
}

.eyebrow span {
  display: block;
  width: 34px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(70, 232, 255, 0.6));
}

.eyebrow span:last-child { transform: scaleX(-1); }

.logo {
  margin: 0;
  font-family: var(--sans);
  font-size: clamp(58px, 11.5vw, 132px);
  line-height: 0.82;
  font-weight: 900;
  letter-spacing: 0.035em;
  color: #f2fbff;
  text-shadow:
    0 0 18px rgba(70, 232, 255, 0.35),
    0 0 70px rgba(70, 232, 255, 0.22),
    0 8px 40px rgba(0, 0, 0, 0.8);
}

.logo span {
  color: var(--magenta);
  text-shadow:
    0 0 18px rgba(255, 63, 158, 0.5),
    0 0 70px rgba(255, 63, 158, 0.32);
}

.logo-sub {
  margin: 10px 0 0;
  padding-left: 0.68em;
  color: var(--cyan);
  font-family: var(--mono);
  font-size: clamp(9px, 1.4vw, 13px);
  font-weight: 700;
  letter-spacing: 0.68em;
  text-shadow: 0 0 16px rgba(70, 232, 255, 0.6);
}

.tagline {
  margin: 18px 0 0;
  color: var(--muted);
  font-size: clamp(12px, 1.5vw, 15px);
  letter-spacing: 0.06em;
}

.btn {
  position: relative;
  min-width: 190px;
  padding: 15px 34px;
  border: 1px solid var(--cyan);
  background: transparent;
  color: var(--cyan);
  font-family: var(--mono);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  cursor: pointer;
  clip-path: polygon(12px 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%, 0 12px);
  transition: background 0.16s ease, color 0.16s ease, box-shadow 0.16s ease, transform 0.16s ease;
}

.btn.primary {
  margin-top: 30px;
  background: linear-gradient(100deg, rgba(70, 232, 255, 0.16), rgba(70, 232, 255, 0.04));
  box-shadow: 0 0 24px rgba(70, 232, 255, 0.16), inset 0 0 24px rgba(70, 232, 255, 0.08);
}

.btn.primary::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(100deg, transparent 20%, rgba(255, 255, 255, 0.35) 50%, transparent 80%);
  transform: translateX(-120%);
  transition: transform 0.5s ease;
}

.btn.primary:hover::before,
.btn.primary:focus-visible::before { transform: translateX(120%); }

.btn:hover,
.btn:focus-visible {
  background: var(--cyan);
  color: #041018;
  box-shadow: 0 0 34px rgba(70, 232, 255, 0.55);
  outline: none;
}

.btn:active { transform: translateY(1px) scale(0.99); }

.btn.ghost {
  border-color: rgba(138, 162, 184, 0.35);
  color: var(--muted);
}

.btn.ghost:hover,
.btn.ghost:focus-visible {
  background: rgba(138, 162, 184, 0.16);
  color: var(--ink);
  border-color: var(--muted);
  box-shadow: none;
}

.brief {
  width: min(560px, 92vw);
  margin-top: 36px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border-top: 1px solid rgba(120, 220, 255, 0.14);
  border-bottom: 1px solid rgba(120, 220, 255, 0.14);
}

.brief > div {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 13px 10px;
  border-right: 1px solid rgba(120, 220, 255, 0.12);
}

.brief > div:last-child { border-right: 0; }

.brief b {
  color: var(--cyan);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.32em;
}

.brief span {
  color: rgba(170, 200, 220, 0.72);
  font-size: 11px;
  letter-spacing: 0.04em;
}

.menu-foot {
  margin: 22px 0 0;
  color: rgba(138, 162, 184, 0.65);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.26em;
}

.menu-foot .sep { margin: 0 10px; color: rgba(70, 232, 255, 0.5); }

.panel {
  width: min(520px, 92vw);
  padding: clamp(28px, 4vw, 46px) clamp(22px, 4vw, 46px);
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  background: var(--panel);
  border: 1px solid rgba(120, 220, 255, 0.18);
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.65), inset 0 0 60px rgba(70, 232, 255, 0.03);
  clip-path: polygon(22px 0, 100% 0, 100% calc(100% - 22px), calc(100% - 22px) 100%, 0 100%, 0 22px);
  animation: menuIn 0.4s cubic-bezier(0.16, 1, 0.3, 1) both;
}

.panel h2 {
  margin: 4px 0 0;
  font-size: clamp(34px, 6vw, 56px);
  font-weight: 900;
  letter-spacing: 0.04em;
  line-height: 1;
  color: var(--cyan);
  text-shadow: 0 0 30px rgba(70, 232, 255, 0.45);
}

.panel h2.danger {
  color: var(--danger);
  text-shadow: 0 0 30px rgba(255, 77, 109, 0.5);
}

.panel h2.good {
  color: var(--green);
  text-shadow: 0 0 30px rgba(124, 255, 178, 0.45);
}

.eyebrow.danger { color: var(--danger); }
.eyebrow.danger span { background: linear-gradient(90deg, transparent, rgba(255, 77, 109, 0.65)); }
.eyebrow.good { color: var(--green); }
.eyebrow.good span { background: linear-gradient(90deg, transparent, rgba(124, 255, 178, 0.65)); }

.stats {
  width: 100%;
  margin-top: 28px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border-top: 1px solid rgba(120, 220, 255, 0.14);
  border-bottom: 1px solid rgba(120, 220, 255, 0.14);
}

.stats > div {
  display: flex;
  flex-direction: column;
  gap: 7px;
  padding: 16px 6px;
  border-right: 1px solid rgba(120, 220, 255, 0.12);
}

.stats > div:last-child { border-right: 0; }

.stats span {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.3em;
}

.stats b {
  color: var(--ink);
  font-family: var(--mono);
  font-size: clamp(18px, 2.6vw, 26px);
  letter-spacing: 0.04em;
}

.newbest {
  margin: 16px 0 0;
  color: var(--amber);
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.34em;
  text-shadow: 0 0 16px rgba(255, 209, 102, 0.7);
  animation: bestPulse 0.9s ease-in-out infinite alternate;
}

@keyframes bestPulse {
  from { opacity: 0.55; }
  to { opacity: 1; }
}

.button-row {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
  margin-top: 28px;
}

.button-row .btn { margin-top: 0; }

/* -------------------------------------------------------------- responsive */

@media (hover: none), (pointer: coarse) {
  .bomb-btn { display: flex; align-items: center; justify-content: center; }
  .hint { bottom: 92px; }
}

@media (max-width: 780px) {
  .hud { padding: 12px 14px 12px; }
  .hud-top { gap: 8px; }
  .wave-block { min-width: 0; }
  .wave-name { display: none; }
  .best-line { display: none; }
  .meter-group:nth-child(2) { display: none; }
  .right-block { gap: 8px; }
  .stat-value { font-size: 24px; }
  .wave-label { font-size: 10px; letter-spacing: 0.2em; }
  .boss-wrap { width: 30vw; min-width: 90px; margin-top: 4px; }
  .boss-name { display: none; }
  .pip { width: 12px; height: 15px; }
  .hud-buttons { gap: 5px; }
  .icon-btn { width: 30px; height: 30px; }
  .powerups { bottom: 2px; }
  .chip i { width: 42px; }
  .hint { font-size: 8px; letter-spacing: 0.12em; }
  .menu-inner { width: 100%; }
  .sigil { width: 58px; height: 58px; margin-bottom: 14px; }
  .brief { margin-top: 26px; }
  .brief > div { padding: 11px 5px; }
  .brief span { font-size: 9px; }
  .menu-foot { letter-spacing: 0.16em; }
  .toast { top: 18%; }
}

@media (max-width: 520px) {
  .overlay { padding: 16px; }
  .eyebrow { letter-spacing: 0.2em; font-size: 8px; }
  .logo { font-size: clamp(54px, 17vw, 84px); }
  .tagline { margin-top: 14px; font-size: 12px; }
  .brief { grid-template-columns: 1fr; width: 100%; }
  .brief > div {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    border-right: 0;
    border-bottom: 1px solid rgba(120, 220, 255, 0.1);
    padding: 9px 12px;
  }
  .brief > div:last-child { border-bottom: 0; }
  .menu-foot { font-size: 8px; }
  .stats b { font-size: 18px; }
  .button-row { flex-direction: column; width: 100%; }
  .button-row .btn { width: 100%; }
  .btn { min-width: 160px; }
  .hud-bottom { min-height: 60px; }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
}

content.text:
Now game.js. This is the big one. Let's write in sections. Need avoid syntax errors. I'll aim for ~1300 lines but can be less. Let's design exact code.

Top-level IIFE.

Utility functions.

DOM refs.

Audio.

Background.

State and reset.

Input.

Wave plans.

Enemy creation/update.

Player, bullets, pickups, particles.

HUD, overlays.

Render.

Loop.

Let's be meticulous.

Potential issue with `ctx.setTransform(DPR,0,0,DPR,0,0)` and canvas width. Good.

DPR variable name conflicts with DOM? no.

`resize()` called initially and on resize.

State W,H.

Background canvas `bgCanvas`.

Let's write.

```js
(() => {
'use strict';

const $ = (id) => document.getElementById(id);
const canvas = $('game');
const ctx = canvas.getContext('2d', { alpha: false });
```
alpha false maybe black background; okay but clearRect shows black. Use alpha:false improves perf. But background image covers all. On shake we don't shake bg. fine.
Actually with alpha:false, `clearRect` fills black? It clears to black? With alpha false, clearRect gives black. Fine.

DOM refs:
```
const ui = {
 hud: $('hud'), score:..., ...
}
```
Overlays: menu, pause, gameover, victory.

Sound object.

`const store = { get(){...}, set... }`.

Best: 
```
let bestScore = 0;
try { bestScore = Number(localStorage.getItem('starfall.best')||0)||0 } catch {}
```

State:
```
const G = {...}
let W=0,H=0,DPR=1;
```

Stars and bg.

Particles arrays.

Let's code all.

Important: requestAnimationFrame starts at bottom after init.

Audio details:
```
const Sound = {
  ctx: null, master:null, enabled:true, noiseBuf:null, lastShoot:0,
  init() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return; }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    try {
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.enabled ? 0.5 : 0;
      this.master.connect(this.ctx.destination);
      const len = Math.floor(this.ctx.sampleRate * 0.5);
      const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
      const data = buf.getChannelData(0);
      for (let i=0;i<len;i++) data[i] = Math.random()*2-1;
      this.noiseBuf = buf;
    } catch { this.ctx = null; }
  },
  ...
}
```
`tone`:
```
tone(freq, dur, type='sine', vol=0.05, slide=1, delay=0){
 if(!this.ctx||!this.enabled) return;
 const t0=this.ctx.currentTime+delay;
 ...
 osc.frequency.setValueAtTime(freq,t0);
 if (slide!==1) osc.frequency.exponentialRampToValueAtTime(Math.max(20, freq*slide), t0+dur);
 gain.gain.setValueAtTime(0.0001,t0);
 gain.gain.exponentialRampToValueAtTime(Math.max(0.0002,vol),t0+0.008);
 gain.gain.exponentialRampToValueAtTime(0.0001,t0+dur);
 ...
}
```
Note if dur < 0.01 okay. Fine.
noise:
```
noise(dur, vol, cutoff=1200, type='lowpass'){
 if(!this.ctx||!this.enabled||!this.noiseBuf) return;
 const src=this.ctx.createBufferSource(); src.buffer=this.noiseBuf; src.loop=true;
 const filter=this.ctx.createBiquadFilter(); filter.type=type; filter.frequency.value=cutoff;
 const g=...; g.gain.setValueAtTime(vol,t0); exponential...
 src.connect(filter).connect(g).connect(this.master); src.start(t0); src.stop(t0+dur);
}
```
Methods with cooldown:
- shoot: if now-lastShoot < 0.045 return; tone(680+rand,0.05,'triangle',0.022,0.45)
- hit: tone(200,0.04,'square',0.012,0.6)
- explode: noise(.35,.12,700) + tone(80,.28,'sine',.05,.4)
- bigExplode: noise(.8,.22,400)+tone(55,.9,'sine',.1,.3)
- pickup: tone(740,.08,'sine',.05,1.4); tone(1100,.12,'sine',.04,1.5,.06)
- playerHit: noise(.25,.16,500); tone(140,.25,'sawtooth',.05,.5)
- bomb: noise(.7,.22,320); tone(60,.7,'sine',.09,.4)
- wave: tone(420,.12,'triangle',.05,1.3); tone(630,.18,'triangle',.04,1.4,.1)
- boss: tone(70,1.2,'sawtooth',.06,.5); noise(.8,.08,200)
- gameOver: tone(240,.5,'sawtooth',.06,.4); tone(120,.9,'sine',.07,.3,.18)
- victory: sequence [523,659,784,1046] with delays.
- ui click.

Toggle mute updates master gain.

State:
```
const G = {
 mode:'menu',
 score:0, best:bestScore, wave:0, kills:0, shots:0, streak:0, combo:1, comboTimer:0,
 shields:3, maxShields:5, bombs:2, maxBombs:5,
 rapid:0, spread:0, power:0,
 player:null, enemies:[], bullets:[], ebullets:[], particles:[], pickups:[], texts:[], rings:[],
 spawns:[], spawnTimer:0, waveActive:false, waveEndTimer:0, intermission:0, pendingVictory:0,
 boss:null, time:0, gameTime:0, shake:0, flash:0, flashColor:'255,255,255',
 aim:-Math.PI/2, timeScale:1, slowTimer:0,
 pointer:{active:false,x:0,y:0},
 hintTimer:9, hudAcc:0, startedAt:0,
 lastCombo:1, finalWave:10,
}
```
`slowmo`: on boss death set G.slowTimer=0.9; update gameplay dt scaled? If scaled, everything slows including timers. Implement in loop:
```
let dt = ...
if (G.slowTimer>0){ G.slowTimer-=dt; worldScale = 0.35; }
update(dt)
```
But timeScale affects HUD? no. We can apply inside updateGame:
```
const gdt = dt * (G.slowTimer>0 ? 0.35 : 1);
if (G.slowTimer>0) G.slowTimer-=dt;
```
And particles update with gdt too? Use global `G.scale`. Simpler: not implement slowmo; use shake/flash. Skip.

Stars:
```
let stars=[];
function initStars(){
 const count = Math.min(260, Math.round(W*H/7500));
 stars = [];
 for(...) stars.push({x:rand(0,W), y:rand(0,H), z:rand(.25,1), size:rand(.6,1.9), tw:rand(.6,2.2), phase:rand(0,TAU)});
}
```
update stars:
```
function updateStars(dt){
 const sp = (G.mode==='playing'? 26: 8);
 for s of stars { s.y += sp*s.z*dt; s.x += (G.mode==='playing'? -4*s.z*dt:0); if(s.y>H+4){...} if(s.x<-4) s.x=W+4; }
}
```
Maybe stars drift down to imply flying up.

Background build. Use `document.createElement('canvas')`. Need handle DPR. `bg.width=Math.max(1,Math.round(W*DPR))`. Draw with transform.

`nebula` helper:
```
function blob(c,x,y,r,color){ const g=c.createRadialGradient(x,y,0,x,y,r); g.addColorStop(0,color); g.addColorStop(1,'rgba(0,0,0,0)'); c.fillStyle=g; c.fillRect(x-r,y-r,r*2,r*2); }
```
Colors rgba with alpha. `lighter`.

Planet:
```
const pr=Math.max(W,H)*0.62; const px=W*0.88, py=H*1.18;
let pg = c.createRadialGradient(px-pr*0.55, py-pr*0.72, pr*0.05, px, py, pr);
pg.addColorStop(0,'rgba(52,92,150,0.22)'); ... pg.addColorStop(1,'rgba(2,4,12,0.9)');
```
Since planet center below screen, visible top arc. rim stroke maybe with gradient:
```
c.strokeStyle='rgba(90,210,255,0.10)'; lineWidth=2; stroke circle
