function updateEnemies(dt){
 const p=G.player;
 for (const e of G.enemies){
   if(e.dead) continue;
   e.t+=dt;
   e.hitT=Math.max(0,e.hitT-dt);
   if(e.spawnT>0){ e.spawnT-=dt; continue; }
   if(e.boss){ updateBoss(e,dt); continue; }
   const dx=p.x-e.x, dy=p.y-e.y, d=Math.hypot(dx,dy)||1;
   const nx=dx/d, ny=dy/d;
   if(e.type==='shooter'){
      let tx=0,ty=0;
      if(d>290){ tx=nx; ty=ny; } else if(d<210){ tx=-nx; ty=-ny; } else { tx=-ny; ty=nx; }
      e.vx += tx*e.speed*2.2*dt; e.vy += ty*e.speed*2.2*dt;
      const sp=Math.hypot(e.vx,e.vy)||1; const max=e.speed*1.6;
      if(sp>max){ e.vx=e.vx/sp*max; e.vy=e.vy/sp*max; }
      e.fireCd-=dt;
      if(e.fireCd<=0 && p.alive){ e.fireCd = Math.max(.85, 2.1 - G.wave*.06); shootAimed(e, 240+G.wave*4, 1, .12); }
   } else if(e.type==='tank'){
      e.vx += nx*e.speed*1.2*dt; e.vy += ny*e.speed*1.2*dt;
      const sp=Math.hypot(e.vx,e.vy)||1; if(sp>e.speed){...}
      e.fireCd-=dt;
      if(e.fireCd<=0){ e.fireCd=2.8; radialBurst(e.x,e.y, 7, 150, e.t); }
   } else if(e.type==='zigzag'){
      const perp = e.t*3.2+e.phase;
      const vx = nx*e.speed + (-ny)*Math.sin(perp)*110;
      const vy = ny*e.speed + (nx)*Math.sin(perp)*110;
      e.vx=lerp(e.vx,vx,.1); e.vy=lerp(e.vy,vy,.1); // frame dependent; use factor
   } else {
      e.vx += nx*e.speed*2.6*dt; ...
   }
