   // bounce off far bounds? clamp to expanded area? keep inside margin -100..W+100
   e.angle = Math.atan2(e.vy,e.vx);
   // drift if spawnT? no
 }
 // separation
 for(let i=0;i<G.enemies.length;i++){ ... }
}
