  e.aimedCd -= dt;
  e.summonCd -= dt;

  if (e.radialCd <= 0) {
    e.radialCd = phase2 ? 1.55 : 2.4;
    radialBurst(e.x, e.y, phase2 ? 22 : 14, 145 + (phase2 ? 55 : 25), t, phase2 ? '#ff3f9e' : '#ff7a5c', 5);
    Sound.bossShot();
  }
  if (e.aimedCd <= 0) {
    e.aimedCd = phase2 ? 0.9 : 1.45;
    shootAimed(e, 300, phase2 ? 5 : 3, 0.13, '#ff5c7a');
  }
  if (phase2) {
    e.spiralCd -= dt;
    if (e.spiralCd <= 0) {
      e.spiralCd = 0.14;
      e.spiralAngle += 0.36;
      enemyBullet(e.x, e.y, e.spiralAngle, 175, 4, '#ff7ae0');
      enemyBullet(e.x, e.y, e.spiralAngle + Math.PI, 175, 4, '#ff7ae0');
    }
  }
  if (e.summonCd <= 0) {
    e.summonCd = phase2 ? 6 : 8.5;
    const count = e.variant === 2 ? 3 : 2;
    for (let i = 0; i < count; i++) {
      const type = Math.random() < 0.55 ? 'drone' : 'zigzag';
      addEnemy(type, e.x + rand(-95, 95), e.y + rand(-4, 55));
    }
    Sound.bossShot();
  }
}

