import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch(config.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
const errors = []
page.on('pageerror', e => errors.push('pageerror: ' + e.message))
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()) })
await page.goto('http://localhost:3002/?debug=1', { waitUntil: 'load' })
await page.getByRole('button', { name: 'Start Game' }).click()
await page.waitForTimeout(8000)
const state = await page.evaluate(() => ({
  mode: window.__starfall.G.mode,
  wave: window.__starfall.G.wave,
  score: window.__starfall.G.score,
  enemies: window.__starfall.G.enemies.filter(e => !e.dead).length,
  lives: window.__starfall.G.lives,
  fpsMode: window.__starfall.G.mode
}))
// Use keyboard movement briefly to verify input path.
await page.keyboard.down('ArrowLeft'); await page.waitForTimeout(400); await page.keyboard.up('ArrowLeft')
await page.keyboard.press('Space'); await page.waitForTimeout(600)
const after = await page.evaluate(() => ({ pulses: window.__starfall.G.pulses, mode: window.__starfall.G.mode }))
console.log(JSON.stringify({ state, after, errors }, null, 2))
await browser.close()
if (errors.length) process.exitCode = 1

